--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `Order_ID` varchar(8) NOT NULL,
  `order_type` varchar(20) NOT NULL,
  `tanggal_pesan` date NOT NULL,
  `NIK` varchar(20) NOT NULL,
  `email` varchar(73) NOT NULL,
  `latitude_pickup` double NOT NULL,
  `longitude_pickup` double NOT NULL,
  `latitude_dropoff` double NOT NULL,
  `longitude_dropoff` double NOT NULL,
  PRIMARY KEY (`Order_ID`),
  KEY `NIK` (`NIK`),
  KEY `email` (`email`),
  KEY `latitude_pickup` (`latitude_pickup`,`longitude_pickup`),
  KEY `latitude_dropoff` (`latitude_dropoff`,`longitude_dropoff`),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`NIK`) REFERENCES `driver` (`NIK`),
  CONSTRAINT `orders_ibfk_2` FOREIGN KEY (`email`) REFERENCES `user` (`email`),
  CONSTRAINT `orders_ibfk_3` FOREIGN KEY (`latitude_pickup`, `longitude_pickup`) REFERENCES `location` (`latitude`, `longitude`),
  CONSTRAINT `orders_ibfk_4` FOREIGN KEY (`latitude_dropoff`, `longitude_dropoff`) REFERENCES `location` (`latitude`, `longitude`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

