/*!50001 VIEW `statistik_vehicle` AS select (select min(`vehicle`.`kapasitas_kendaraan`) from `vehicle`) AS `Min_kapasitas`,(select max(`vehicle`.`kapasitas_kendaraan`) from `vehicle`) AS `Max_kapasitas`,(select floor(avg(`vehicle`.`kapasitas_kendaraan`)) from `vehicle`) AS `Avg_kapasitas`,(select `vehicle`.`tipe_bahan_bakar` from `vehicle` group by `vehicle`.`tipe_bahan_bakar` order by count(0) desc limit 1) AS `Modus_tipe_bahan_bakar`,(select count(distinct `vehicle`.`tipe_bahan_bakar`) from `vehicle`) AS `Unique_tipe_bahan_bakar`,(select count(0) from `vehicle` where (`vehicle`.`tipe_bahan_bakar` = (select `vehicle`.`tipe_bahan_bakar` from `vehicle` group by `vehicle`.`tipe_bahan_bakar` order by count(0) desc limit 1))) AS `Frequency_Modus_tipe_bahan_bakar`,(select `vehicle`.`jenis_kendaraan` from `vehicle` group by `vehicle`.`jenis_kendaraan` order by count(0) desc limit 1) AS `Modus_jenis_kendaraan`,(select count(distinct `vehicle`.`jenis_kendaraan`) from `vehicle`) AS `Unique_jenis_kendaraan`,(select count(0) from `vehicle` where (`vehicle`.`jenis_kendaraan` = (select `vehicle`.`jenis_kendaraan` from `vehicle` group by `vehicle`.`jenis_kendaraan` order by count(0) desc limit 1))) AS `Frequency_Modus_jenis_kendaraan` from `vehicle` limit 1 */;
