/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `total_harga` AS select `o`.`Order_ID` AS `order_ID`,`prom`.`promo_code` AS `promo_code`,(case when (`o`.`order_type` = 'grab_bike') then `gb`.`harga_awal_motor` when (`o`.`order_type` = 'grab_express') then `ge`.`harga_awal_barang` when (`o`.`order_type` = 'grab_car') then `gc`.`harga_awal_mobil` else 0 end) AS `harga_awal`,ifnull(`prom`.`diskon`,1) AS `diskon`,round(((case when (`o`.`order_type` = 'grab_bike') then `gb`.`harga_awal_motor` when (`o`.`order_type` = 'grab_express') then `ge`.`harga_awal_barang` when (`o`.`order_type` = 'grab_car') then `gc`.`harga_awal_mobil` else 0 end) * (1 - ifnull(`prom`.`diskon`,1))),2) AS `total_harga` from ((((`orders` `o` left join `grab_bike` `gb` on((`o`.`Order_ID` = `gb`.`Order_ID`))) left join `grab_express` `ge` on((`o`.`Order_ID` = `ge`.`Order_ID`))) left join `grab_car` `gc` on((`o`.`Order_ID` = `gc`.`Order_ID`))) left join `promotion` `prom` on((`o`.`email` = `prom`.`email`))) */;
